import { Component, OnInit } from '@angular/core';
import { WeaponService } from "../../service/weapon.service";
import { Weapons } from "../../model/weapons";
import { Weapon } from "../../model/weapon";

@Component({
  selector: 'app-weapon-list',
  templateUrl: './weapon-list.component.html',
  styleUrls: ['./weapon-list.component.css']
})
export class WeaponListComponent implements OnInit {
  constructor(private service: WeaponService) {
  }

  weapons: Weapons | undefined;

  ngOnInit(): void {
    this.service.getWeapons().subscribe(weapons => this.weapons = weapons);
  }

  onDelete(weapon: Weapon): void {
    this.service.deleteWeapon(weapon.id).subscribe(() => this.ngOnInit());
  }

}
<article class="text--justified">
  <header><h2>Weapons</h2></header>

  <table *ngIf="weapons">
    <thead>
      <tr>
        <th>Name</th>
        <th>View</th>
        <th>Edit</th>
        <th>Delete</th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let weapon of weapons.characters">
        <td>{{weapon.name}}</td>
        <td>
          <a [routerLink]="['/weapons', weapon.id]">View</a>
        </td>
        <td>
          <a [routerLink]="['/weapons', weapon.id, 'edit']">Edit</a>
        </td>
        <td>
          <button (click)="onDelete(weapon)">Delete</button>
        </td>
      </tr>
    </tbody>
  </table>
</article>
